```yaml
name: Brin PR Commit Security Scan

on:
  pull_request:
    types: [opened, synchronize, reopened]

permissions:
  contents: read
  pull-requests: write

jobs:
  brin-scan:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          fetch-depth: 0

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Install Brin CLI
        run: npm install -g @brin/cli

      - name: Run Brin Security Scan
        id: brin
        env:
          BRIN_API_KEY: ${{ secrets.BRIN_API_KEY }}
        run: |
          # Get the base and head commits for the PR
          BASE_SHA=$(git merge-base HEAD origin/${{ github.event.pull_request.base.ref }})
          HEAD_SHA=${{ github.event.pull_request.head.sha }}

          # Run Brin scan on the diff
          # Assuming brin CLI supports scanning a range or specific commits
          # If brin requires a specific command structure, adjust accordingly.
          # Here we assume a generic 'brin scan' command that accepts commit ranges or files.
          # Since the exact CLI syntax isn't provided, we simulate the expected behavior based on the prompt.

          # Create a temporary directory for results
          mkdir -p brin-results

          # Run the scan (hypothetical command structure based on typical CLI tools)
          # If brin scans the whole repo, we might need to filter by changed files.
          # For this example, we assume brin can scan the diff between base and head.
          brin scan --range $BASE_SHA..$HEAD_SHA --output brin-results/report.json --format json || true

          # Check if report exists
          if [ ! -f brin-results/report.json ]; then
            echo "No report generated. Assuming clean or error."
            echo "status=clean" >> $GITHUB_OUTPUT
            exit 0
          fi

          # Parse results using jq (install if not present)
          sudo apt-get install -y jq > /dev/null 2>&1

          # Extract metrics
          BLOCKING=$(cat brin-results/report.json | jq '.findings | map(select(.severity == "blocking")) | length')
          REVIEW=$(cat brin-results/report.json | jq '.findings | map(select(.severity == "review")) | length')
          INCONCLUSIVE=$(cat brin-results/report.json | jq '.findings | map(select(.severity == "inconclusive")) | length')
          DANGEROUS=$(cat brin-results/report.json | jq '.findings | map(select(.is_dangerous == true)) | length')

          # Check for low scores (below 30)
          LOW_SCORE_COMMITS=$(cat brin-results/report.json | jq '[.commits[] | select(.score < 30)] | length')

          TOTAL_FINDINGS=$((BLOCKING + REVIEW + INCONCLUSIVE))

          echo "blocking=$BLOCKING" >> $GITHUB_OUTPUT
          echo "review=$REVIEW" >> $GITHUB_OUTPUT
          echo "inconclusive=$INCONCLUSIVE" >> $GITHUB_OUTPUT
          echo "dangerous=$DANGEROUS" >> $GITHUB_OUTPUT
          echo "low_score=$LOW_SCORE_COMMITS" >> $GITHUB_OUTPUT
          echo "total=$TOTAL_FINDINGS" >> $GITHUB_OUTPUT

          # Determine if we should fail
          if [ "$DANGEROUS" -gt 0 ] || [ "$LOW_SCORE_COMMITS" -gt 0 ]; then
            echo "is_failure=true" >> $GITHUB_OUTPUT
          else
            echo "is_failure=false" >> $GITHUB_OUTPUT
          fi

      - name: Update PR Comment
        if: always()
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const { blocking, review, inconclusive, dangerous, low_score, total, is_failure } = {
              blocking: parseInt(process.env.BLOCKING || '0'),
              review: parseInt(process.env.REVIEW || '0'),
              inconclusive: parseInt(process.env.INCONCLUSIVE || '0'),
              dangerous: parseInt(process.env.DANGEROUS || '0'),
              low_score: parseInt(process.env.LOW_SCORE || '0'),
              total: parseInt(process.env.TOTAL || '0'),
              is_failure: process.env.IS_FAILURE === 'true'
            };

            const prNumber = context.issue.number;
            const commentBody = `## Brin Security Scan Results

            **Summary:**
            - Blocking: ${blocking}
            - Review: ${review}
            - Inconclusive: ${inconclusive}
            - Dangerous Commits: ${dangerous}
            - Low Score Commits (<30): ${low_score}

            ${is_failure ? '❌ **Scan Failed:** One or more commits are marked as dangerous or have a security score below 30.' : '✅ **Scan Passed:** No critical security issues found.'}

            ---
            *Scan performed by Brin*`;

            // Find existing comment
            const comments = await github.rest.issues.listComments({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
            });

            const existingComment = comments.data.find(comment => 
              comment.body.includes('## Brin Security Scan Results')
            );

            if (total === 0 && !is_failure) {
              // If clean, remove comment if it exists
              if (existingComment) {
                await github.rest.issues.deleteComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: existingComment.id,
                });
              }
            } else {
              // Update or create comment
              if (existingComment) {
                await github.rest.issues.updateComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  comment_id: existingComment.id,
                  body: commentBody,
                });
              } else {
                await github.rest.issues.createComment({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  issue_number: prNumber,
                  body: commentBody,
                });
              }
            }

      - name: Fail if dangerous or low score
        if: steps.brin.outputs.is_failure == 'true'
        run: exit 1
